import { Client, Environment } from 'square';
import { randomUUID } from 'crypto';

const client = new Client({
  accessToken: process.env.SQUARE_ACCESS_TOKEN!,
  environment: Environment.Sandbox,
});

const { checkoutApi } = client;

// Create a payment link for a quick sale
const { result, statusCode } = await checkoutApi.createPaymentLink({
  idempotencyKey: randomUUID(),
  quickPay: {
    name: 'Pro Plan Subscription',
    priceMoney: {
      amount: BigInt(2000), // Amount in cents — must be BigInt in the Square SDK
      currency: 'USD',
    },
    locationId: process.env.SQUARE_LOCATION_ID!,
  },
  checkoutOptions: {
    redirectUrl: 'https://yourapp.com/checkout/success',
    askForShippingAddress: false,
  },
  prePopulatedData: {
    buyerEmail: 'customer@example.com',
  },
});

if (result.errors && result.errors.length > 0) {
  console.error('Square API errors:', result.errors);
  throw new Error(result.errors.map((e) => e.detail).join(', '));
}

const paymentLink = result.paymentLink;
console.log('Payment link URL:', paymentLink?.url);
console.log('Payment link ID:', paymentLink?.id);
// Redirect the customer to paymentLink.url

import { Client, Environment, CatalogObjectType } from 'square';
import { randomUUID } from 'crypto';

const client = new Client({
  accessToken: process.env.SQUARE_ACCESS_TOKEN!,
  environment: Environment.Sandbox,
});

const { catalogApi } = client;

// Create a catalog item (e.g., a menu item) with a price variation
const itemId = `#item-${randomUUID()}`;
const variationId = `#variation-${randomUUID()}`;

const { result, statusCode } = await catalogApi.upsertCatalogObject({
  idempotencyKey: randomUUID(),
  object: {
    type: CatalogObjectType.Item,
    id: itemId,
    itemData: {
      name: 'Espresso',
      description: 'Double shot espresso',
      variations: [
        {
          type: CatalogObjectType.ItemVariation,
          id: variationId,
          itemVariationData: {
            itemId: itemId,
            name: 'Regular',
            pricingType: 'FIXED_PRICING',
            priceMoney: {
              amount: BigInt(350), // $3.50 — must be BigInt
              currency: 'USD',
            },
            trackInventory: false,
          },
        },
      ],
    },
  },
});

if (result.errors && result.errors.length > 0) {
  console.error('Failed to create catalog item:', result.errors);
  throw new Error(result.errors.map((e) => e.detail).join(', '));
}

const createdItem = result.catalogObject;
console.log('Created catalog item ID:', createdItem?.id);
console.log('Variation ID:', createdItem?.itemData?.variations?.[0]?.id);
